def compute(vars):
    aggregate_cost = vars["v1"]
    fair_value = vars["v2"]

    if fair_value == 0:
        return None

    ratio = aggregate_cost / fair_value
    return {
        "value": ratio,
        "trace": {
            "aggregate_cost": aggregate_cost,
            "fair_value": fair_value,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
